package com.example;

import org.eclipse.core.runtime.FileLocator;
import org.eclipse.core.runtime.Path;
import org.eclipse.jface.resource.ImageDescriptor;
import org.osgi.framework.Bundle;

public class TestClass {
    public ImageDescriptor getImage(Bundle bundle, String iconPath) {
        // Assume bundle and iconPath are valid
        return ImageDescriptor.createFromURL(FileLocator.find(bundle, new Path(iconPath), null));
    }
}

afterExample:
package com.example;

import org.eclipse.core.runtime.FileLocator;
import org.eclipse.core.runtime.Path;
import org.eclipse.jface.resource.ImageDescriptor;
import org.osgi.framework.Bundle;

public class TestClass {
    public ImageDescriptor getImage(Bundle bundle, String iconPath) {
        // Assume bundle and iconPath are valid
        return ImageDescriptor.createFromURLSupplier(true, () -> FileLocator.find(bundle, new Path(iconPath), null));
    }
}

